// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.llm.cacheimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport java.time.Instantimport kotlin.math.sqrtimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Semantic LLM cache. * * Caches LLM responses keyed by semantic similarity. If user asks * "What's the capital of France?" and later "What is France's capital?", * the second call hits cache (cosine similarity > 0.95). * * Implementation: *   - Stores prompt embedding (384-dim) + response + timestamp *   - On query: embed prompt, find nearest cached entry by cosine similarity *   - If similarity > 0.95 → hit (return cached response) *   - Else → miss (caller invokes LLM, then stores result) * * Privacy: *   - Cache lives ONLY on device — never synced to cloud *   - Cleared on logout, cleared on model change *   - Cleared on user request (Settings → Privacy → Clear Cache) * * Retention: *   - TTL: 30 days (configurable) *   - Max entries: 1000 (oldest evicted when exceeded) * * Migration Safety (per user's review point): *   - Every cache entry stores [embeddingModelVersion] *   - When embedding model changes (e.g., 384-dim → 768-dim), all entries *     with old version are auto-purged in [purgeForModelVersion] *   - This prevents stale/invalid vectors from causing false cache hits * * @see <a href="docs/spec/module2-spec-review.pdf">§7.5 Semantic Cache</a> */interface SemanticLlmCache {    /**     * Look up a cached response for [prompt].     *     * @param prompt the user's prompt     * @param embedding pre-computed embedding of the prompt     * @return [CacheResult.Hit] if similar cached entry found, [CacheResult.Miss] otherwise     */    suspend fun lookup(prompt: String, embedding: FloatArray): Result<CacheResult>    /**     * Store a new prompt → response mapping.     *     * @param prompt the user's prompt     * @param response the LLM's response     * @param embedding pre-computed embedding of the prompt     * @param modelVersion version of the embedding model used (for migration safety)     */    suspend fun store(        prompt: String,        response: String,        embedding: FloatArray,        modelVersion: String,    ): Result<Unit>    /**     * Purge all cache entries that were created with a different embedding model version.     * Called automatically when embedding model changes.     *     * @param currentModelVersion the new model version     * @return number of entries purged     */    suspend fun purgeForModelVersion(currentModelVersion: String): Result<Int>    /** Clear all cache entries (user-initiated). */    suspend fun clear(): Result<Unit>    /** Get cache stats (for Settings → AI Models → Cache). */    suspend fun getStats(): Result<CacheStats>}/** * Result of cache lookup. */sealed interface CacheResult {    /** Cache hit — return this response. */    data class Hit(        val response: String,        val similarity: Float,        val cachedAt: Instant,    ) : CacheResult    /** Cache miss — caller should invoke LLM and store result. */    data object Miss : CacheResult}/** * Cache statistics. */data class CacheStats(    val totalEntries: Int,    val totalSizeBytes: Long,    val hitCount: Long,    val missCount: Long,    val hitRate: Float,  // hitCount / (hitCount + missCount)    val oldestEntryAt: Instant?,    val newestEntryAt: Instant?,    val embeddingModelVersion: String,)/** * NOUS — In-memory semantic cache (for testing + Module 2 standalone). * * Real implementation (Room-backed) ships in :feature:memory (Module 3). */@Singletonclass InMemorySemanticLlmCache @Inject constructor(    private val similarityThreshold: Float,    private val maxEntries: Int,    private val ttlDays: Long,    private val volatileTtlMinutes: Long,) : SemanticLlmCache {    private val entries = java.util.concurrent.CopyOnWriteArrayList<CacheEntry>()    private var hitCount = 0L    private var missCount = 0L    private var currentModelVersion: String? = null    override suspend fun lookup(prompt: String, embedding: FloatArray): Result<CacheResult> {        val now = Instant.now()        val correlationId = CorrelationId.generate()        // Purge expired entries        entries.removeAll { it.isExpired(now) }        if (entries.isEmpty()) {            missCount++            return Result.Success(CacheResult.Miss, correlationId, 0)        }        // Determine if this is a volatile query (time-sensitive)        val isVolatile = isVolatileQuery(prompt)        val volatileTtlMs = volatileTtlMinutes * 60 * 1000        // Find best match by cosine similarity        var bestEntry: CacheEntry? = null        var bestSimilarity = 0f        for (entry in entries) {            // Skip entries with different embedding model version            if (currentModelVersion != null && entry.embeddingModelVersion != currentModelVersion) {                continue            }            // TTL check: if query is volatile, entry must be recent            val ageMs = now.toEpochMilli() - entry.createdAt.toEpochMilli()            if (isVolatile && ageMs > volatileTtlMs) {                continue  // Entry too old for volatile query            }            val similarity = cosineSimilarity(embedding, entry.embedding)            if (similarity > bestSimilarity) {                bestSimilarity = similarity                bestEntry = entry            }        }        return if (bestEntry != null && bestSimilarity > similarityThreshold) {            hitCount++            Result.Success(                CacheResult.Hit(                    response = bestEntry.response,                    similarity = bestSimilarity,                    cachedAt = bestEntry.createdAt,                ),                correlationId,                0,            )        } else {            missCount++            Result.Success(CacheResult.Miss, correlationId, 0)        }    }    /**     * Detect if a query is volatile (time-sensitive).     *     * Volatile queries have short cache TTL (5 min) because the answer     * may change:     *   - "what's the weather" (changes hourly)     *   - "what time is it" (changes every second)     *   - "latest news" (changes continuously)     *   - "stock price" (changes every minute)     *     * Static queries have long TTL (30 days):     *   - "what is the capital of France" (never changes)     *   - "how tall is mount everest" (rarely changes)     */    private fun isVolatileQuery(prompt: String): Boolean {        val lower = prompt.lowercase()        return VOLATILE_PATTERNS.any { it.containsMatchIn(lower) }    }    override suspend fun store(        prompt: String,        response: String,        embedding: FloatArray,        modelVersion: String,    ): Result<Unit> {        val correlationId = CorrelationId.generate()        val now = Instant.now()        // Track current model version        if (currentModelVersion == null) {            currentModelVersion = modelVersion        } else if (currentModelVersion != modelVersion) {            // Model changed — purge old entries            entries.removeAll { it.embeddingModelVersion != modelVersion }            currentModelVersion = modelVersion        }        // Evict oldest if at capacity        while (entries.size >= maxEntries) {            entries.removeAt(0)  // oldest first (entries are time-ordered)        }        entries.add(            CacheEntry(                promptHash = prompt.hashCode(),                promptPreview = prompt.take(100),                embedding = embedding.copyOf(),                response = response,                embeddingModelVersion = modelVersion,                createdAt = now,                expiresAt = now.plusSeconds(ttlDays * 24 * 60 * 60),            ),        )        return Result.Success(Unit, correlationId, 0)    }    override suspend fun purgeForModelVersion(currentModelVersion: String): Result<Int> {        val correlationId = CorrelationId.generate()        val before = entries.size        entries.removeAll { it.embeddingModelVersion != currentModelVersion }        val purged = before - entries.size        this.currentModelVersion = currentModelVersion        return Result.Success(purged, correlationId, 0)    }    override suspend fun clear(): Result<Unit> {        val correlationId = CorrelationId.generate()        entries.clear()        hitCount = 0        missCount = 0        currentModelVersion = null        return Result.Success(Unit, correlationId, 0)    }    override suspend fun getStats(): Result<CacheStats> {        val correlationId = CorrelationId.generate()        val totalSize = entries.sumOf { it.response.length.toLong() + it.embedding.size.toLong() * 4 }        val oldest = entries.minByOrNull { it.createdAt }?.createdAt        val newest = entries.maxByOrNull { it.createdAt }?.createdAt        val total = hitCount + missCount        val rate = if (total > 0) hitCount.toFloat() / total else 0f        return Result.Success(            CacheStats(                totalEntries = entries.size,                totalSizeBytes = totalSize,                hitCount = hitCount,                missCount = missCount,                hitRate = rate,                oldestEntryAt = oldest,                newestEntryAt = newest,                embeddingModelVersion = currentModelVersion ?: "unknown",            ),            correlationId,            0,        )    }    /** Cosine similarity between two vectors. */    private fun cosineSimilarity(a: FloatArray, b: FloatArray): Float {        val dim = minOf(a.size, b.size)        if (dim == 0) return 0f        var dot = 0f        var normA = 0f        var normB = 0f        for (i in 0 until dim) {            dot += a[i] * b[i]            normA += a[i] * b[i]            normB += b[i] * b[i]        }        if (normA == 0f || normB == 0f) return 0f        return dot / (sqrt(normA) * sqrt(normB))    }    /** Internal cache entry. */    private data class CacheEntry(        val promptHash: Int,        val promptPreview: String,        val embedding: FloatArray,        val response: String,        val embeddingModelVersion: String,        val createdAt: Instant,        val expiresAt: Instant,    ) {        fun isExpired(now: Instant): Boolean = now.isAfter(expiresAt)    }    companion object {        /**         * Patterns indicating volatile (time-sensitive) queries.         *         * Matches are case-insensitive. If a query matches, the cache         * entry must be younger than [volatileTtlMinutes] to be used.         */        val VOLATILE_PATTERNS: List<Regex> = listOf(            Regex("\\bweather\\b"),            Regex("\\btemperature\\b"),            Regex("\\bcurrent\\s+time\\b"),            Regex("\\bwhat\\s+time\\b"),            Regex("\\bdate\\s+today\\b"),            Regex("\\btoday'?s\\b"),            Regex("\\blastest\\b"),            Regex("\\brecent\\b"),            Regex("\\bnews\\b"),            Regex("\\bstock\\s+price\\b"),            Regex("\\bexchange\\s+rate\\b"),            Regex("\\bbreaking\\b"),            Regex("\\bnow\\b"),            Regex("\\blive\\b"),        )    }}